import test from 'node:test';
import assert from 'node:assert/strict';
import {initialState,project,loadScenario,decisionFirst,decide,compare,prioritize,validate} from './model.js';
import {definition} from '../../../embed/definitions/lab-context.js';
import {validateState} from '../../../embed/core/schema.js';
const fresh=()=>structuredClone(initialState);
test('specific fact loss changes the default decision at the portfolio layer',()=>{const r=project(fresh());assert.equal(r.decision.choice,'launch');assert.equal(r.full.choice,'hold');assert.equal(r.lostAt.blocker,1);assert.ok(r.layers[0].carried.includes('blocker'));assert.ok(!r.layers[1].carried.includes('blocker'));assert.ok(!r.layers[2].received.includes('blocker'));});
test('prioritising decision conditions retains the blocker with the same capacities',()=>{const a=fresh(),b=decisionFirst(a);assert.deepEqual(a.capacities,b.capacities);assert.equal(project(b).decision.choice,'hold');assert.equal(project(b).differs,false);});
test('short reports can preserve the routine decision with less reading',()=>{const s=loadScenario(fresh(),'routine'),small=project(s);s.capacities=[24,24,24];const full=project(s);assert.equal(small.decision.choice,full.decision.choice);assert.equal(small.differs,false);assert.ok(small.reading<full.reading);});
test('missing is distinct from false and explicit policy controls unresolved evidence',()=>{assert.equal(decide({ready:99},80,'hold').choice,'hold');assert.equal(decide({ready:99},80,'pilot').choice,'pilot');assert.equal(decide({ready:99,blocker:false,rollback:true,dependency:true},80,'hold').choice,'launch');assert.equal(decide({ready:99,rollback:false},80,'launch').choice,'pilot');assert.equal(decide({ready:99,rollback:false,blocker:true},80,'launch').choice,'hold');});
test('source retrieval restores omitted facts only within the decision window',()=>{const s=fresh();s.queries=['rollback','blocker'];s.decisionWindow=1;let r=project(s);assert.deepEqual(r.retrieved,['rollback']);assert.deepEqual(r.unanswered,['blocker']);assert.equal(r.decision.choice,'launch');s.decisionWindow=2;r=project(s);assert.equal(r.decision.choice,'hold');assert.equal(r.queryTime,2);});
test('facts already present need no source request time',()=>{const s=fresh();s.queries=['ready','blocker'];s.decisionWindow=1;const r=project(s);assert.deepEqual(r.alreadyPresent,['ready']);assert.deepEqual(r.retrieved,['blocker']);assert.equal(r.queryTime,1);});
test('the next small fact may fit after a larger higher-priority fact is skipped',()=>{const s=decisionFirst(fresh());s.capacities[0]=1;const r=project(s);assert.deepEqual(r.layers[0].carried,['dependency']);assert.ok(r.layers[0].dropped.includes('blocker'));});
test('moving later priority cannot resurrect an upstream omission',()=>{const s=fresh();s.capacities[0]=1;const moved=prioritize(s,2,'blocker',0);assert.ok(!project(moved).layers[2].carried.includes('blocker'));assert.equal(s.orders[2][0],'ready');assert.equal(moved.orders[2][0],'blocker');});
test('matched comparison shares source values and costs, not pinned old facts',()=>{const pinned=decisionFirst(fresh()),s=loadScenario(fresh(),'routine');s.costs.blocker=4;const c=compare(s,pinned);assert.equal(c.state.facts.blocker,false);assert.equal(c.state.costs.blocker,4);assert.deepEqual(c.state.orders,pinned.orders);assert.equal(c.situationChanged,true);});
test('malformed order, excessive capacities, extra facts and duplicate queries are rejected',()=>{for(const change of [s=>s.orders[0][0]='blocker',s=>s.capacities[0]=25,s=>s.facts.extra=1,s=>s.queries=['ready','ready'],s=>s.facts.ready=NaN]){const s=fresh();change(s);assert.throws(()=>validate(s));}});
test('portable definition validates and renders narrow and wide source-derived views',()=>{validateState(definition,fresh());for(const width of [320,1100]){const v=definition.views.report.render(fresh(),{width});assert.match(v.svg,/<svg/);assert.match(v.summary,/launch/);assert.doesNotMatch(v.svg,/NaN|undefined/);}});
